{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "This article is the final version of a living systematic review that has been updated over the past two years to reflect emerging evidence.",
      "reason": "The manuscript explicitly describes itself as a 'living systematic review', indicating the report is a systematic review (title and metadata of the document also use 'systematic review')."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "To provide an overview of available prediction models, a living systematic review, with periodic updates, was conducted by the international covid-PRECISE ... Hence our aim was to systematically review and critically appraise available prognostic models for detecting people in the general population at increased risk of covid-19 infection or being admitted to hospital or dying with the disease, and models to predict the prognosis or course of infection in patients with a covid-19 diagnosis.",
      "reason": "The review aim and scope are clearly stated (prediction models for diagnosis/prognosis of COVID-19, populations addressed include general population and patients with COVID-19), which corresponds to key objective information reflected in the title."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "MISSING",
      "chunk_id": "text_5",
      "quote": "Living systematic review and critical appraisal by the covid-PRECISE (Precise Risk Estimation to optimise covid-19 Care for Infected or Suspected patients in diverse sEttings) group.",
      "reason": "The title (document metadata) does not include supplementary information such as update status or analysis method; although the manuscript notes it is a 'living systematic review' elsewhere, the title itself does not provide additional supplementary details like update number, included study designs, analysis method, or living-review status beyond indicating 'systematic review and critical appraisal'."
    }
  ],
  "confidence": "70"
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "The outbreak of covid-19 was accompanied by a surge of scientific evidence. 9 The speed with which evidence about covid-19 has accumulated is unprecedented. To provide an overview of available prediction models, a living systematic review, with periodic updates, was conducted by the international covid-PRECISE (Precise Risk Estimation to optimise covid-19 Care for Infected or Suspected patients in diverse sEttings; https://www.covprecise.org/) group in collaboration with the Cochrane Prognosis Methods Group.",
      "reason": "Describes the current state (rapid, unprecedented accumulation of evidence) and contextualises the review as a living systematic review to address that evolving evidence base, indicating key uncertainties about available prediction models."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Hence our aim was to systematically review and critically appraise available prognostic models for detecting people in the general population at increased risk of covid-19 infection or being admitted to hospital or dying with the disease, and models to predict the prognosis or course of infection in patients with a covid-19 diagnosis.",
      "reason": "Explicitly states the importance and need for the review by defining its aim to systematically review and critically appraise prognostic models to inform practice amid rapidly accumulating COVID-19 prediction literature."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "This article is the final version of a living systematic review that has been updated over the past two years to reflect emerging evidence. This version is update 4 of the original article published on 7 April 2020 ( BMJ 2020;369:m1328). Previous updates can be found as data supplements (https:/ /www.bmj.com/ content/369/bmj.m1328/related#datasupp).",
      "reason": "States that this is an updated living systematic review, cites the original publication and prior updates, and explains the relationship to previous reviews/versions."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review concerns prediction models, not intervention effects; no intervention mechanism of action is discussed in the provided evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not address complex interventions or delivery contexts and provides no logic model; therefore this reporting element is not applicable."
    }
  ],
  "confidence": "90"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "To review and appraise the validity and usefulness of published and preprint reports of prediction models for prognosis of patients with covid-19, and for detecting people in the general population at increased risk of covid-19 infection or being admitted to hospital or dying with the disease.",
      "reason": "The manuscript provides an explicit statement of the review objectives, specifying the focus on prediction models for prognosis and for detecting people at increased risk. However, the objectives are not framed using a formal question-formulation framework (eg, PICO or a prediction-focused variant), so the requirement to state objectives using a relevant framework is not fully met."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_11",
      "quote": "To provide an overview of available prediction models, a living systematic review, with periodic updates, was conducted ... Hence our aim was to systematically review and critically appraise available prognostic models for detecting people in the general population at increased risk of covid-19 infection or being admitted to hospital or dying with the disease, and models to predict the prognosis or course of infection in patients with a covid-19 diagnosis.",
      "reason": "The review concerns prediction/prognostic models rather than intervention effects; planned comparisons using PICO for interventions are not applicable."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "We included studies if they developed or validated a multivariable model or scoring system, based on individual participant level data, to predict any covid-19 related outcome. These models included prognostic models to predict the course of infection in patients with covid-19; and prediction models to identify people in the general population at risk of covid-19 infection or at risk of being admitted to hospital or dying with the disease. Diagnostic models to predict the presence or severity of covid-19 in patients with suspected infection were included up to update 3 only, which can be found in the data supplements.",
      "reason": "The manuscript specifies the core eligible study characteristic (development or validation of multivariable prediction models using individual participant data) and the target settings (prognostic in patients and general population; diagnostic models limited to earlier updates). It does not fully enumerate other study characteristic details (eg, eligible study designs, explicit follow-up requirements or all PICO-framework components)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit eligibility criteria for report characteristics (dissemination year, language, publication or report status) are stated in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not report a distinction between excluding studies because outcomes were not measured versus excluding because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "callout_1",
      "quote": "These prognostic models can be divided into models to predict the risk of developing covid-19 or having an adverse disease course in the general population (n=13), and models to support the prognosis of patients with covid-19 (n=593).",
      "reason": "The review specifies groups used in synthesis (general population models vs prognostic models for patients) and links them to the outcomes/comparisons of interest."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "Diagnostic models to predict the presence or severity of covid-19 in patients with suspected infection were included up to update 3 only, which can be found in the data supplements.",
      "reason": "The manuscript documents at least one notable restriction on eligibility (diagnostic models only included through an earlier update), but it does not provide an explicit rationale for this restriction in the retrieved evidence."
    }
  ],
  "confidence": "75"
}

