{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PARTIAL",
      "chunk_id": "callout_0",
      "quote": "We identified 13 newly developed models aiming to predict covid-19 related risks in the general population. Five models predicted hospital admission for covid-19, three predicted mortality, one predicted development of severe covid-19, and four predicted an insufficiently defined covid-19 outcome.",
      "reason": "The manuscript reports multiple outcome domains (e.g. hospital admission, mortality, severe COVID-19) and notes use of proxy outcomes in some models, but does not provide comprehensive definitions for all outcome domains sought (many outcomes are described at a high level and some are noted as 'insufficiently defined')."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PARTIAL",
      "chunk_id": "callout_1",
      "quote": \"These studies were too heterogeneous and biased to meta-analyse: they used varying outcome definitions (mortality, ICU admission, various composites, with time horizons varying from 1 to 30 days), from different populations (Italy, UK, Norway, China), and were at high or unclear risk of bias.\",
      "reason": "The review reports that outcome time horizons in the included studies varied (gives range 1 to 30 days) and notes variation in follow-up, but does not specify the time frame of measurement for each outcome domain sought by the review itself."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement was found indicating whether the review sought all results compatible with each outcome domain (for all measures, time points, analyses) or describing that decision."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No description located of a process used to select results within outcome domains when not all compatible results were sought."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information found reporting changes to outcome-domain inclusion, definitions, or importance with rationales."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information found reporting changes to the processes for selecting results within eligible outcome domains with rationales."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No statement was identified about which outcomes were considered most important for interpreting conclusions nor a rationale for any prioritisation."
    }
  ],
  "confidence": 65
}

